#!/bin/bash
# route by path instead of by User-Agent: the registry API (/v2/) goes to the Docker repository connector, the rest to the web application
set -e
W=/tmp/bench76836830
CONF=$W/nginx/nginx.conf
python3 - "$CONF" <<'PYEOF'
import re, sys
p = sys.argv[1]; s = open(p).read()
s = re.sub(r"        location / \{.*?\n        \}\n", '''        location /v2/ {
            proxy_pass http://127.0.0.1:15076;
        }
        location / {
            proxy_pass http://127.0.0.1:18176;
        }
''', s, flags=re.S)
open(p, "w").write(s)
PYEOF
$W/bin/nginxctl test
$W/bin/nginxctl reload
sleep 1
$W/bin/pull

